package ociresources

import (
	"github.com/anthnel/devdesk/internal/jobs"
	"github.com/anthnel/devdesk/internal/ui/components"
	"github.com/anthnel/devdesk/internal/ui/indicator"
)

// ociKinds are the operations whose activity or remembered failure an Images
// row shows: a scan or a pull, whoever started it (D5).
var ociKinds = []jobs.Kind{jobs.KindScan, jobs.KindPull}

// rowActivity resolves what one Images row says about its activity, read from
// the router snapshot against the context it carries. The identity is the raw
// reference, never a canonical form. A removal in flight is this view's own
// observation: it is reported as Running with its label.
func (m Model) rowActivity(r imageRow) components.RowActivity {
	q := components.RowQuery{
		Runs: m.jobs, Failures: m.failures, Context: m.contextName,
		Target: jobs.TargetKey(r.RawName), Kinds: ociKinds,
	}
	if label, ok := m.imageTable.BusyLabel(r.Image.ID); ok {
		q.Observed = indicator.Running
		q.ObservedText = label
	}
	return components.DescribeRow(q)
}

// scanRunning reports whether a scan of the image is running now in the
// current context. A queued scan is not running.
func (m Model) scanRunning(name string) bool { return m.runningOn(name, jobs.KindScan) }

// pullRunning reports whether a pull of the image is running now in the
// current context. A queued pull is not running.
func (m Model) pullRunning(name string) bool { return m.runningOn(name, jobs.KindPull) }

func (m Model) runningOn(name string, kind jobs.Kind) bool {
	for _, a := range jobs.ActiveOn(m.jobs, m.contextName, name, kind) {
		if a.Item.State == jobs.ItemRunning {
			return true
		}
	}
	return false
}
	}
	if len(queue) == 0 {
		return m, nil
	}
	return m, tea.Batch(
		deleteScanCacheCmd(cacheKeys),
		jobs.Start(m.scanRun(cacheKeys), batchScanCmd(queue, m.scanOptions())),
	)
}

// handleImageScanStarting drops whatever the footer still said about the last
// attempt.
//
// The row is already spinning: the router recorded the transition before handing
// the message on, and the snapshot that carried it rebuilt the table. There is
// no chain to restart either — the router holds the only one (D5).
func (m Model) handleImageScanStarting(_ ImageScanStartingMsg) (tea.Model, tea.Cmd) {
	m.footer.Clear()
	return m, nil
}

// handleImageScanFinished updates scan results for a completed image scan.
func (m Model) handleImageScanFinished(msg ImageScanFinishedMsg) (tea.Model, tea.Cmd) {
	if msg.Err != nil {
		m.failedScans[msg.ImageName] = true
	} else {
		delete(m.failedScans, msg.ImageName)
		m.scanCache[msg.ImageName] = msg.Entry
		m.footer.Clear()
	}
	m.updateImageTable()
	if m.registryBrowser != nil {
		m.registryBrowser.SetScanCache(m.scanCache)
	}
	return m, nil
}

// handleScanRequest rescans one image by name, whoever asked.
//
// The router sends this when a cached scan's stored result has gone missing:
// the row is still in the list, and the scan that would replace it belongs
// here, next to the cache it writes. The name is both the cache key and the
// scan target, as it is for an image typed rather than picked.
func (m Model) handleScanRequest(msg ScanRequestMsg) (tea.Model, tea.Cmd) {
	if msg.ImageName == "" || m.scanningImage(msg.ImageName) {
		return m, nil
	return append(cols, datatable.Column[imageRow]{
		Title: "Scanned", Sizing: datatable.SizingFixed, Optional: true, MinWidth: 14,
		Cell:  scannedCell,
		Style: scannedStyle,
		Less:  func(a, b imageRow) bool { return a.Entry.ScannedAt.Before(b.Entry.ScannedAt) },
	})
}

// imageRows decorates the image list with the scan state the table shows,
// plus a placeholder row for any pull in flight whose image is not local yet.
func (m *Model) imageRows() []imageRow {
	aliases := registryalias.From(m.registries)
	pulling := m.pullingNames()

	seen := make(map[string]bool, len(m.images))
	rows := make([]imageRow, 0, len(m.images))
	for _, img := range m.images {
		raw := img.Name()
		seen[raw] = true
		entry, scanned := m.scanCache[raw]
		row := imageRow{
			Image:       img,
			DisplayName: docker.ApplyAliases(raw, aliases),
			RawName:     raw,
			Entry:       entry,
			Scanned:     scanned,
			ScanRunning: m.scanRunning(raw),
			Failed:      m.failedScans[raw],
			PullRunning: m.pullRunning(raw),
			Update:      m.imageUpdate(img),
			Signature:   m.imageSignature(img),
		}
		row.Activity = m.rowActivity(row)
		rows = append(rows, row)
	}
	// An image pulled for the first time has no local row to spin yet — this
	// is the common case when pulling from the registry browser, so it gets
	// a placeholder rather than staying invisible until the pull completes.
	for name := range pulling {
		if seen[name] {
			continue
		}
		row := imageRow{
			DisplayName: docker.ApplyAliases(name, aliases),
			RawName:     name,
			ScanRunning: m.scanRunning(name),
			PullRunning: m.pullRunning(name),
		}
		row.Activity = m.rowActivity(row)
		rows = append(rows, row)
	}
	return rows
}

// imageUpdate is the Update cell of an image (§3.88). An untagged image names
// nothing to ask about; one without a registry digest was built or loaded here,
// and is never sent to a registry (pulledImageRefs).
func (m *Model) imageUpdate(img docker.Image) imageupdate.Status {
	switch {
	case img.Tag == "" || img.Tag == "<none>":
		return imageupdate.Status{}
package jobs

import (
	"path/filepath"
	"slices"
	"time"
)

// MaxFailures caps how many remembered failures the registry keeps.
const MaxFailures = 500

// FailureKey identifies what failed: an operation kind on one target in one
// context. Target is always a TargetKey.
type FailureKey struct {
	Kind    Kind
	Target  string
	Context string
}

// Failure is the last remembered failure for a FailureKey. The registry
// stores it with an already normalized key.
type Failure struct {
	FailureKey
	// Display is the human-readable name of the target.
	Display string
	// Detail is the failure reason.
	Detail string
	At     time.Time
}

// TargetKey normalizes a target so every view naming the same thing produces
// the same key. Only absolute paths are cleaned; image references, forge
// paths and slugs are kept verbatim, since two spellings of an image
// ("nginx", "nginx:latest") are not provably the same target.
func TargetKey(target string) string {
	if filepath.IsAbs(target) {
		return filepath.Clean(target)
	}
	return target
}

// FailureFor returns the failure remembered for kind on target in
// contextName. The target is normalized with TargetKey.
func FailureFor(failures []Failure, kind Kind, target, contextName string) (Failure, bool) {
	key := FailureKey{Kind: kind, Target: TargetKey(target), Context: contextName}
	for _, f := range failures {
		if f.FailureKey == key {
			return f, true
		}
	}
	return Failure{}, false
}

// FailuresOn returns a copy of the failures on target in contextName, in the
// order of the input slice. With no kinds, every kind is kept. An empty
// target is not special: it matches only failures stored with an empty target.
func FailuresOn(failures []Failure, contextName, target string, kinds ...Kind) []Failure {
	target = TargetKey(target)
	var out []Failure
	for _, f := range failures {
		if f.Context != contextName || f.Target != target {
			continue
		}
		if len(kinds) > 0 && !slices.Contains(kinds, f.Kind) {
			continue
		}
		out = append(out, f)
	}
	return out
}
