			t.Errorf("line %d is %d cells wide at 60 columns: %q", i, w, ansi.Strip(line))
		}
	}
	tables := a.views[command.ViewSecurity].(activityView).ActivityTables()
	tb, ok := tables["sec/inventory"]
	if !ok {
