// scannedStyle colours the scan state, a failure being the one value in the
// column that asks for anything.
func scannedStyle(r imageRow) lipgloss.Style {
	switch {
	case r.Failed:
		return theme.StatusErrorStyle
	case r.ScanRunning, !r.Scanned:
		return theme.DimStyle
	}
	// No opinion here: the table sets the theme's text color.
	return lipgloss.NewStyle()
}

// scannedCell reports the scan state: "scanning" while one runs, an error icon
// when the last attempt failed, otherwise how long ago it succeeded.
func scannedCell(r imageRow) string {
	switch {
	case r.ScanRunning:
		return "scanning"
	case r.Failed:
		return theme.IconError + " error"
	case r.Scanned:
		return timeAgo(r.Entry.ScannedAt)
	}
	return "-"
}

// imageColumns describes the Images tab. ID is the only column that neither
// sorts nor searches — twelve hex characters are not something anyone orders or
// looks for.
func imageColumns(withMisconfig bool) []datatable.Column[imageRow] {
	cols := []datatable.Column[imageRow]{
		// The activity column (Rule 125): untitled, no Less nor Search. At rest
		// it shows the image icon.
		datatable.IndicatorColumn(
			func(r imageRow) indicator.State { return r.Activity.State },
			func(imageRow) string { return theme.IconDocker },
			func(imageRow) lipgloss.Style { return theme.IconStyle(theme.IconRoleImage) },
	switch {
	case len(m.InUse) > 0:
		t.State = jobs.ItemFailed
		t.Detail = "not updated — the image is in use"
	case isBlocked(m.Err):
		// The reason, not "check logs": it names the rule, and it is what an
		// agent that asked for the pull reads (§3.82).
		t.State = jobs.ItemFailed
		t.Detail = "refused — " + m.Err.Error()
	case m.Err != nil:
		t.State = jobs.ItemFailed
		t.Detail = "pull failed — check logs"
	}
	return t
}

// Compile-time proof that every progress message can be applied. One added
// without a transition would leave its row spinning for the life of the view.
var (
	_ jobs.Reporter = ImageScanStartingMsg{}
	_ jobs.Reporter = ImageScanFinishedMsg{}
	_ jobs.Reporter = RegistryPullStartingMsg{}
